css:
:root{color-scheme:light dark}
body{margin:0;padding:2rem 1.25rem;max-width:72ch;margin-inline:auto;font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#1a1a1a;background:#ffffff}
pre{overflow:auto;padding:1rem;background:#f0f0f0;border-radius:6px}
.tk-k{color:#0a7550}.tk-s{color:#0550ae}.tk-a{color:#7c3aed}.tk-p{color:#5b6876}.tk-c{color:#5b6876;font-style:italic}.fmrl-cb{background:#f0f0f0;color:#5b6876}.fmrl-cb:hover{background:#e2e2e2;color:#1a1a1a}.fmrl-cb.fmrl-cb-done{color:#0a7550}.fmrl-cb:focus-visible{outline:2px solid #0a7550;outline-offset:2px}.fmrl-cb::after{background:#ffffff;color:#1a1a1a}
@media (prefers-color-scheme:dark){body{color:#e6e6e6;background:#111111}pre{background:#1e1e1e}.tk-k{color:#3ddc97}.tk-s{color:#79c0ff}.tk-a{color:#d2a8ff}.tk-p{color:#8b98a5}.tk-c{color:#8b98a5;font-style:italic}.fmrl-cb{background:#1e1e1e;color:#8b98a5}.fmrl-cb:hover{background:#2c2c2c;color:#e6e6e6}.fmrl-cb.fmrl-cb-done{color:#3ddc97}.fmrl-cb:focus-visible{outline:2px solid #3ddc97;outline-offset:2px}.fmrl-cb::after{background:#111111;color:#e6e6e6}}
h1,h2,h3{line-height:1.25}
code{font:.92em ui-monospace,SFMono-Regular,Menlo,monospace}
img{max-width:100%}
table{border-collapse:collapse}
td,th{border:1px solid rgba(127,127,127,.4);padding:.35rem .6rem}
blockquote{margin:0;padding-left:1rem;border-left:3px solid rgba(127,127,127,.5);color:inherit;opacity:.85}
a{color:#0b63c4}
.fmrl-cb-wrap{position:relative}
.fmrl-cb{position:absolute;top:6px;right:6px;display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;padding:0;border:0;border-radius:7px;cursor:pointer;opacity:0;transition:opacity .12s;-webkit-user-select:none;user-select:none}
.fmrl-cb-wrap:hover .fmrl-cb,.fmrl-cb:focus-visible,.fmrl-cb-done{opacity:1}
@media (hover:none){.fmrl-cb{opacity:1}}
.fmrl-cb svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.fmrl-cb::after{content:attr(data-tip);position:absolute;top:calc(100% + 7px);right:0;padding:5px 8px;border:1px solid rgba(127,127,127,.4);border-radius:6px;font:500 .7rem/1 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .12s;z-index:1}
.fmrl-cb:hover::after,.fmrl-cb:focus-visible::after{opacity:1}
.fmrl-cb-status{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;-webkit-user-select:none;user-select:none}

copyJS:
// copy.js gives each code block of a rendered Markdown document a copy
// button, as /install's blocks have: the copy glyph, "copy" as its tip, and
// a check with "copied" for two seconds once the block is on the clipboard.
//
// It runs inside the viewer's sandboxed frame, whose opaque origin is not
// delegated clipboard-write, so navigator.clipboard is refused there by
// permissions policy. What every engine does allow is copying a selection
// inside the click, which is what write() does; see it for why the
// selection is not optional.
//
// The button goes beside the <pre>, in a wrapper, never inside <code>, so a
// block's text stays the fence body byte for byte; its label is aria-label
// and the tip is CSS content, so selecting the page never takes it.
(function () {
  var COPY = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"></rect><path d="M5 15V5a2 2 0 012-2h10"></path></svg>';
  var CHECK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12l5 5L20 7"></path></svg>';

  // write puts text on the clipboard and reports whether it did.
  //
  // It copies a selection, because that is the only copy every engine
  // performs: Chromium fires a copy event for execCommand with nothing
  // selected, but Firefox and Safari make it a no-op, so intercepting the
  // event copies nothing there. A readonly off-screen textarea holds the
  // text, is selected and copied inside the click, and goes again, with the
  // reader's own selection and focus put back — the selection the way round
  // they made it, so Shift+Arrow still extends from the end they were
  // moving, and the focus without scrolling, since Safari does not focus a
  // button on a click and the element they left focused may be far up the
  // page. readonly keeps a phone's keyboard down and setSelectionRange is
  // what selects it on iOS.
  //
  // The Clipboard API is the fallback, not the first choice: the viewer's
  // frame is not delegated clipboard-write, so it is refused there by
  // permissions policy, and it is asked only if the copy above did not
  // happen (a document saved and opened on its own).
  function write(text) {
    var active = document.activeElement;
    var sel = window.getSelection();
    var saved = [];
    var ends = null;
    if (sel) {
      // One range goes back by its ends, which carry the direction; the
      // several a reader can make in Firefox go back as ranges.
      if (sel.rangeCount === 1 && sel.anchorNode && sel.setBaseAndExtent) {
        ends = [sel.anchorNode, sel.anchorOffset, sel.focusNode, sel.focusOffset];
      }
      for (var i = 0; i < sel.rangeCount; i++) {
        saved.push(sel.getRangeAt(i));
      }
    }
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;padding:0;border:0;opacity:0';
    document.body.appendChild(ta);
    var ok = false;
    try {
      ta.focus({ preventScroll: true });
      ta.select();
      ta.setSelectionRange(0, text.length);
      ok = document.execCommand('copy');
    } catch (e) {
      ok = false;
    }
    ta.remove();
    if (sel) {
      sel.removeAllRanges();
      if (ends) {
        sel.setBaseAndExtent(ends[0], ends[1], ends[2], ends[3]);
      } else {
        for (var j = 0; j < saved.length; j++) {
          sel.addRange(saved[j]);
        }
      }
    }
    if (active && active.focus) {
      active.focus({ preventScroll: true });
    }
    if (ok) {
      return Promise.resolve();
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text);
    }
    return Promise.reject(new Error('no clipboard'));
  }

  // A changed aria-label is not reliably announced, so a copy is also said
  // through one polite live region. Each copy empties it and writes the
  // words again a moment later, so a repeat copy is heard, and one shared
  // timer empties it two seconds after the latest copy, so an earlier
  // button's reset cannot silence a newer one. It takes no part in a
  // selection of the page.
  var statusTimer;
  var status = document.createElement('div');
  status.className = 'fmrl-cb-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');

  function copied(btn) {
    clearTimeout(btn.fmrlTimer);
    clearTimeout(statusTimer);
    status.textContent = '';
    statusTimer = setTimeout(function () {
      status.textContent = 'Copied code';
      statusTimer = setTimeout(function () { status.textContent = ''; }, 2000);
    }, 100);
    btn.innerHTML = CHECK;
    btn.dataset.tip = 'copied';
    btn.setAttribute('aria-label', 'copied');
    btn.classList.add('fmrl-cb-done');
    btn.fmrlTimer = setTimeout(function () {
      btn.innerHTML = COPY;
      btn.dataset.tip = 'copy';
      btn.setAttribute('aria-label', 'copy code');
      btn.classList.remove('fmrl-cb-done');
    }, 2000);
  }

  var codes = document.querySelectorAll('pre > code');
  if (codes.length) {
    document.body.appendChild(status);
  }
  for (var i = 0; i < codes.length; i++) {
    (function (code) {
      var pre = code.parentNode;
      var wrap = document.createElement('div');
      wrap.className = 'fmrl-cb-wrap';
      pre.parentNode.insertBefore(wrap, pre);
      wrap.appendChild(pre);
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'fmrl-cb';
      btn.dataset.tip = 'copy';
      btn.setAttribute('aria-label', 'copy code');
      btn.innerHTML = COPY;
      wrap.appendChild(btn);
      btn.addEventListener('click', function () {
        write(code.textContent).then(function () { copied(btn); }, function () {});
      });
    })(codes[i]);
  }
})();
